// Load scenario definitions from workflow static data
const sd = getWorkflowStaticData('global');

// Initialize scenarios if not present
sd.scenarios = sd.scenarios || {
  "winter_emergency_surge": {
    "description": "Cold snap causes HVAC failures",
    "event_count": 50,
    "time_spread_minutes": 120,
    "event_distribution": {
      "emergency": 0.60,
      "inquiry": 0.25,
      "appointment": 0.10,
      "complaint": 0.05
    },
    "urgency_bias": "high",
    "time_pattern": "evening_heavy",
    "customer_pool": [1, 2, 3, 4],
    "revenue_range": [250, 600]
  },
  "routine_maintenance_day": {
    "description": "Normal business day",
    "event_count": 30,
    "time_spread_minutes": 480,
    "event_distribution": {
      "appointment": 0.50,
      "inquiry": 0.25,
      "follow_up": 0.15,
      "maintenance": 0.10
    },
    "urgency_bias": "low",
    "time_pattern": "business_hours",
    "customer_pool": [1, 2, 3, 4, 5],
    "revenue_range": [150, 350]
  },
  "summer_heatwave": {
    "description": "AC failures during heat emergency",
    "event_count": 75,
    "time_spread_minutes": 180,
    "event_distribution": {
      "emergency": 0.70,
      "inquiry": 0.20,
      "complaint": 0.10
    },
    "urgency_bias": "extreme",
    "time_pattern": "afternoon_spike",
    "customer_pool": [1, 2, 5],
    "revenue_range": [300, 800]
  }
};

// Get requested scenario or default
const scenarioName = $input.item.json.scenario_name || 'routine_maintenance_day';
const scenario = sd.scenarios[scenarioName];

if (!scenario) {
  throw new Error(`Unknown scenario: ${scenarioName}. Available: ${Object.keys(sd.scenarios).join(', ')}`);
}

// Allow overrides from webhook
const eventCount = $input.item.json.event_count || scenario.event_count;
const timeSpread = $input.item.json.time_spread_minutes || scenario.time_spread_minutes;

// Global policy settings
sd.policy = sd.policy || {
  max_events_per_run: 200,
  max_duration_seconds: 120,
  idempotency_ttl_seconds: 300,
  enable_jitter: true,
  jitter_minutes: 5
};

return {
  scenario_name: scenarioName,
  scenario: {
    ...scenario,
    event_count: eventCount,
    time_spread_minutes: timeSpread
  },
  policy: sd.policy,
  timestamp: new Date().toISOString()
};

// Generate unique run ID (ULID-style)
function generateRunId() {
  const timestamp = Date.now().toString(36).toUpperCase();
  const random = Math.random().toString(36).substring(2, 10).toUpperCase();
  return `GEN-${timestamp}-${random}`;
}

// Generate workflow sequence ID (UUID v4)
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const scenario = $input.item.json.scenario;
const scenarioName = $input.item.json.scenario_name;
const policy = $input.item.json.policy;

// Initialize state
const state = {
  run_id: generateRunId(),
  workflow_sequence_id: generateUUID(),
  scenario_name: scenarioName,
  goal: `Generate ${scenario.event_count} events for ${scenarioName}`,
  constraints: {
    max_events: scenario.event_count,
    time_spread_minutes: scenario.time_spread_minutes,
    respect_patterns: true
  },
  counters: {
    events_created: 0,
    events_deduped: 0,
    errors: 0,
    current_step: 0,
    start_time: Date.now()
  },
  scratchpad: {
    plan: `Create ${scenario.event_count} events following ${scenario.time_pattern} pattern`,
    progress: "Initializing...",
    observations: []
  },
  scenario: scenario,
  policy: policy
};

return state;

// Pure JSON Contract: Generate next event specification
const state = $input.item.json;
const scenario = state.scenario;
const counters = state.counters;

// Helper: Generate ULID-style action ID
function actionId() {
  return Date.now().toString(36).toUpperCase() + 
         Math.random().toString(36).substring(2, 10).toUpperCase();
}

// Helper: Select event type based on distribution
function selectEventType(distribution) {
  const rand = Math.random();
  let cumulative = 0;

  for (const [eventType, probability] of Object.entries(distribution)) {
    cumulative += probability;
    if (rand <= cumulative) return eventType;
  }

  return "inquiry";
}

// Helper: Calculate urgency based on event type and bias
function calculateUrgency(eventType, urgencyBias) {
  const baseUrgency = {
    "emergency": [8, 9, 10],
    "complaint": [5, 6, 7],
    "inquiry": [3, 4, 5],
    "appointment": [2, 3, 4],
    "follow_up": [1, 2, 3],
    "maintenance": [2, 3, 4]
  };

  let range = baseUrgency[eventType] || [3, 4, 5];

  if (urgencyBias === "high") {
    range = range.slice(-2);
  } else if (urgencyBias === "extreme") {
    range = [Math.max(...range)];
  }

  return range[Math.floor(Math.random() * range.length)];
}

// Helper: Calculate event timestamp with pattern
function calculateTimestamp(scenario, eventIndex, totalEvents) {
  const startTime = counters.start_time;
  const spreadMs = scenario.time_spread_minutes * 60 * 1000;

  let baseOffset = (spreadMs / totalEvents) * eventIndex;

  if (scenario.time_pattern === "evening_heavy") {
    const threshold = totalEvents * 0.7;
    if (eventIndex > threshold) {
      baseOffset = spreadMs * 0.7 + 
                   (eventIndex - threshold) * (spreadMs * 0.3) / (totalEvents * 0.3);
    }
  } else if (scenario.time_pattern === "afternoon_spike") {
    const midStart = totalEvents * 0.3;
    const midEnd = totalEvents * 0.7;
    if (eventIndex > midStart && eventIndex < midEnd) {
      baseOffset = spreadMs * 0.3 + 
                   (eventIndex - midStart) * (spreadMs * 0.4) / (midEnd - midStart);
    }
  }

  const jitter = state.policy.enable_jitter ? 
                 (Math.random() - 0.5) * state.policy.jitter_minutes * 60 * 1000 : 0;

  return new Date(startTime + baseOffset + jitter);
}

// Helper: Generate description
function generateDescription(eventType, urgency) {
  const descriptions = {
    "emergency": [
      "Furnace completely out, temperature dropping fast",
      "AC unit failed during heatwave",
      "Water heater leaking, flooding basement",
      "Strange burning smell from HVAC unit",
      "No heat, family with young children"
    ],
    "inquiry": [
      "Question about annual maintenance schedule",
      "Interested in upgrading to smart thermostat",
      "Need quote for new AC installation",
      "Asking about filter replacement options",
      "Want to schedule routine inspection"
    ],
    "appointment": [
      "Schedule annual maintenance check",
      "Book time for AC tune-up",
      "Need appointment for filter replacement",
      "Schedule follow-up after last repair",
      "Book consultation for system upgrade"
    ],
    "complaint": [
      "Technician was late to appointment",
      "Repair didn't fix the problem",
      "Unexpected charges on invoice",
      "Noisy HVAC after recent service",
      "Dissatisfied with response time"
    ],
    "follow_up": [
      "Following up on repair from last week",
      "Checking if parts order arrived",
      "Status update on pending maintenance",
      "Question about recent service visit",
      "Confirming appointment for tomorrow"
    ],
    "maintenance": [
      "Quarterly maintenance due",
      "Filter replacement reminder",
      "Annual inspection scheduled",
      "Preventive maintenance check",
      "System performance review"
    ]
  };

  const options = descriptions[eventType] || descriptions["inquiry"];
  return options[Math.floor(Math.random() * options.length)];
}

// Helper: Calculate revenue
function calculateRevenue(eventType, scenario) {
  const [min, max] = scenario.revenue_range;
  const base = min + Math.random() * (max - min);

  const multipliers = {
    "emergency": 1.5,
    "maintenance": 0.7,
    "appointment": 0.8,
    "inquiry": 0.5,
    "follow_up": 0.6,
    "complaint": 0.3
  };

  const multiplier = multipliers[eventType] || 1.0;
  return Math.round(base * multiplier * 100) / 100;
}

// Check if done
if (counters.events_created >= scenario.event_count) {
  return {
    control: {
      done: true,
      reason: "budget_reached"
    },
    next_action: {
      type: "respond",
      message: `Successfully generated ${counters.events_created} events for ${state.scenario_name}`
    },
    state_update: {
      observation: "All events created",
      confidence: 1.0
    }
  };
}

// Generate next event specification
const eventIndex = counters.events_created;
const eventType = selectEventType(scenario.event_distribution);
const urgency = calculateUrgency(eventType, scenario.urgency_bias);
const customerId = scenario.customer_pool[
  Math.floor(Math.random() * scenario.customer_pool.length)
];
const timestamp = calculateTimestamp(scenario, eventIndex, scenario.event_count);
const description = generateDescription(eventType, urgency);
const revenue = calculateRevenue(eventType, scenario);

return {
  control: {
    done: false,
    reason: "ok"
  },
  next_action: {
    type: "create_event",
    action_id: actionId(),
    event_data: {
      event_type: eventType,
      event_timestamp: timestamp.toISOString(),
      customer_id: customerId,
      urgency: urgency,
      description: description,
      estimated_revenue: revenue,
      event_payload: {
        generated_by: "event_generator",
        scenario: state.scenario_name,
        pattern: scenario.time_pattern,
        event_index: eventIndex + 1,
        total_events: scenario.event_count
      },
      is_manual_trigger: false,
      scenario_name: state.scenario_name
    }
  },
  state_update: {
    plan: `Creating event ${eventIndex + 1}/${scenario.event_count}`,
    observation: `Generated ${eventType} event for customer ${customerId}`,
    confidence: 0.98
  },
  state: state
};

// Validate Pure JSON Contract output
const output = $input.item.json;

function fail(msg) {
  throw new Error(`Contract violation: ${msg}`);
}

if (!output || typeof output !== 'object') fail('Output is not an object');
if (!output.control) fail('Missing control object');
if (typeof output.control.done !== 'boolean') fail('control.done must be boolean');
if (!output.next_action) fail('Missing next_action object');
if (!['create_event', 'respond', 'error'].includes(output.next_action.type)) {
  fail(`Invalid next_action.type: ${output.next_action.type}`);
}

if (output.next_action.type === 'create_event') {
  const ed = output.next_action.event_data;
  if (!ed) fail('create_event missing event_data');
  if (!ed.event_type) fail('event_data missing event_type');
  if (!ed.customer_id) fail('event_data missing customer_id');
  if (typeof ed.urgency !== 'number' || ed.urgency < 1 || ed.urgency > 10) {
    fail('urgency must be number 1-10');
  }
  if (!ed.description) fail('event_data missing description');
  if (typeof ed.estimated_revenue !== 'number') fail('estimated_revenue must be number');
}

if (!output.state_update) fail('Missing state_update');
if (typeof output.state_update.confidence !== 'number') fail('confidence must be number');

return {
  ...output,
  validated: true,
  validation_timestamp: new Date().toISOString()
};

// Idempotency check for event generation
const output = $input.item.json;
const eventData = output.next_action.event_data;
const policy = output.state.policy;

function stableHash(obj) {
  if (obj === null || typeof obj !== 'object') return JSON.stringify(obj);
  if (Array.isArray(obj)) return JSON.stringify(obj.map(stableHash));

  const sorted = {};
  Object.keys(obj).sort().forEach(key => {
    sorted[key] = stableHash(obj[key]);
  });
  return JSON.stringify(sorted);
}

const keyComponents = {
  scenario: eventData.scenario_name,
  type: eventData.event_type,
  customer: eventData.customer_id,
  urgency: eventData.urgency,
  timestamp: eventData.event_timestamp
};

const idempotencyKey = `event_gen|${stableHash(keyComponents)}`;

const sd = getWorkflowStaticData('global');
sd._event_cache = sd._event_cache || {};

const now = Date.now();
const ttlMs = policy.idempotency_ttl_seconds * 1000;

for (const key of Object.keys(sd._event_cache)) {
  if (sd._event_cache[key].expires_at < now) {
    delete sd._event_cache[key];
  }
}

const cached = sd._event_cache[idempotencyKey];

if (cached && cached.expires_at >= now && cached.event_id) {
  return {
    ...output,
    deduped: true,
    idempotency_key: idempotencyKey,
    cached_event_id: cached.event_id,
    cache_hit_at: new Date().toISOString()
  };
}

sd._event_cache[idempotencyKey] = {
  created_at: now,
  expires_at: now + ttlMs,
  event_id: null
};

return {
  ...output,
  deduped: false,
  idempotency_key: idempotencyKey,
  cache_miss_at: new Date().toISOString()
};

// Log cache hit
const item = $input.item.json;

return {
  run_id: item.state.run_id,
  workflow_sequence_id: item.state.workflow_sequence_id,
  action: "cache_hit",
  idempotency_key: item.idempotency_key,
  cached_event_id: item.cached_event_id,
  scenario_name: item.state.scenario_name,
  event_type: item.next_action.event_data.event_type,
  timestamp: new Date().toISOString(),
  message: "Event creation skipped (idempotency cache hit)"
};

// Update state after event creation
const output = $input.all()[0].json;
const eventId = $('PostgreSQL Insert Event').item.json.event_id;
const deduped = output.deduped || false;

const state = JSON.parse(JSON.stringify(output.state));

state.counters.current_step += 1;

if (deduped) {
  state.counters.events_deduped += 1;
} else {
  state.counters.events_created += 1;

  const sd = getWorkflowStaticData('global');
  if (sd._event_cache && sd._event_cache[output.idempotency_key]) {
    sd._event_cache[output.idempotency_key].event_id = eventId;
  }
}

const created = state.counters.events_created;
const total = state.scenario.event_count;
const pct = Math.round((created / total) * 100);

state.scratchpad.progress = `Created ${created}/${total} events (${pct}%)`;
state.scratchpad.observations.push(
  deduped ? 
    `Step ${state.counters.current_step}: Deduped ${output.next_action.event_data.event_type}` :
    `Step ${state.counters.current_step}: Created ${output.next_action.event_data.event_type} (ID: ${eventId})`
);

if (state.scratchpad.observations.length > 5) {
  state.scratchpad.observations = state.scratchpad.observations.slice(-5);
}

return state;

// Format final success response
const state = $input.item.json;

const durationMs = Date.now() - state.counters.start_time;
const durationSec = (durationMs / 1000).toFixed(2);

return {
  status: "success",
  run_id: state.run_id,
  workflow_sequence_id: state.workflow_sequence_id,
  scenario_name: state.scenario_name,
  summary: {
    events_created: state.counters.events_created,
    events_deduped: state.counters.events_deduped,
    total_steps: state.counters.current_step,
    errors: state.counters.errors,
    duration_seconds: parseFloat(durationSec),
    events_per_second: (state.counters.events_created / parseFloat(durationSec)).toFixed(2)
  },
  scenario: {
    description: state.scenario.description,
    event_count: state.scenario.event_count,
    time_spread_minutes: state.scenario.time_spread_minutes,
    pattern: state.scenario.time_pattern
  },
  observations: state.scratchpad.observations,
  message: `Successfully generated ${state.counters.events_created} events in ${durationSec}s`,
  timestamp: new Date().toISOString()
};
